        // dropAfter: 這些事件 0.3 秒內剛響過就整個不播(spec: 任務完成那一刻只留 quest_done)
        if (ev.dropAfter) for (var q = 0; q < ev.dropAfter.length; q++) { var z = lastAt[ev.dropAfter[q]]; if (z !== undefined && t - z < 0.3) return; }
